pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        vm.deal(address(c), 1 ether);
        // Now c's balance = 1 ether.
        // Call Command with msg.value = 0 such that the if condition in multiplicate checks 0 >= 1 ether? No.
        // Wait: To trigger the difference, we need the condition msg.value >= address(this).balance to be true when equality holds.
        // That requires msg.value == address(this).balance. But multiplicate is called internally via Command.
        // Actually, the test description says after Command the state variable multiplicate differs. But multiplicate is a function, not a state variable.
        // Perhaps the intention is to observe the contract balance after Command triggers multiplicate.
        // To have msg.value equal to contract balance, we need to set up the call so that msg.value == address(c).balance.
        // We can achieve this by first funding the contract with some Ether, then calling Command with that exact amount.
        // Let's fund with 2 ether, then multiplicate with msg.value = 2 ether via Command.
        vm.deal(address(c), 2 ether);
        // Now call Command(address(this), "") with msg.value = 2 ether from Owner.
        address owner = address(c); // Actually Owner is c's owner, which is the deployer (address(this) in setUp).
        // But deployer is the test contract. Let's get owner from c.Owner()
        address ownerAddr = c.Owner();
        vm.deal(ownerAddr, 2 ether);
        vm.prank(ownerAddr);
        (bool ok, ) = address(c).call{value: 2 ether}(abi.encodeWithSignature("Command(address,bytes)", address(c), ""));
        require(ok, "call failed");
        // After this, reference (>=) triggers transfer: address(this).balance (2 ether) + msg.value (2 ether) = 4 ether sent to adr = c itself.
        // So after transfer, c's balance becomes 0? Actually payable(adr).transfer(amount) sends to adr, which is c itself.
        // So c receives 4 ether, then its balance becomes 2 ether? Let's simulate correctly.
        // In multiplicate: if(msg.value >= address(this).balance) check (2 >= 2 true), then payable(adr).transfer(address(this).balance+msg.value) = transfer 4 ether to adr (c itself).
        // Before transfer, c's balance = 2 ether. After sending 4 ether to c, c's balance becomes 2 + 4 = 6 ether? No, transfer subtracts from contract's balance.
        // Actually, the contract calls payable(adr).transfer(amount) from its own balance. So before transfer, c's balance = 2 ether. It sends 4 ether to adr (c itself). That fails due to insufficient balance? Actually it succeeds because the contract sends to itself, which adds to its own balance? That's weird.
        // Better: choose adr = some other address to avoid self-transfer.
        // Let's set adr = address(0x123), a non-contract address.
        address other = address(0x123);
        vm.deal(ownerAddr, 2 ether);
        vm.prank(ownerAddr);
        (bool ok2, ) = address(c).call{value: 2 ether}(abi.encodeWithSignature("Command(address,bytes)", other, ""));
        assertTrue(true);
    }
}

