pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with 2 ether via receive()
        vm.deal(address(this), 2 ether);
        (bool success, ) = address(c).call{value: 2 ether}("");
        require(success, "receive failed");

        // Now contract balance is 2 ether. We want msg.value == contract balance for multiplicate.
        // But multiplicate checks msg.value >= address(this).balance. To trigger equality condition,
        // we first withdraw 1 ether to make contract balance = 1 ether.
        vm.prank(c.Owner());
        c.withdraw(); // sends 1 ether to Owner (test contract), leaving 1 ether in contract

        // Now contract balance = 1 ether. Call Command to invoke multiplicate with msg.value = 1 ether.
        // This will satisfy equality in reference (>=) but not in buggy (>).
        bytes memory empty;
        vm.deal(address(this), 1 ether);
        vm.prank(c.Owner());
        c.Command{value: 1 ether}(address(this), empty);

        // After call, reference's multiplicate transfers entire balance (2 ether) to address(this),
        // leaving contract balance = 0. Buggy version leaves 1 ether.
        assertTrue(address(c).balance == 0, "balance should be 0 in reference but non-zero in bug");
    }
}

