pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up: fund contract with 1 ether
        vm.deal(address(c), 1 ether);
        // Owner sends a multiplicate call via Command with value equal to contract balance
        address adr = address(0x1234);
        bytes memory data = abi.encodeWithSignature("multiplicate(address)", adr);
        vm.deal(address(this), 1 ether);
        vm.prank(c.Owner());
        // The call should revert in P (reference) but succeed in M (mutant)
        bool ok;
        try c.Command{value: 1 ether}(adr, data) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: require fails => revert => ok == false
        // Mutant: no require => success => ok == true
        assertTrue(ok == false, "Reference should revert");
    }
}

