pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x123);
        address bob = address(0x456);
        vm.deal(alice, 10 ether);
        vm.prank(alice);
        c.Command{value: 3 ether}(address(c), "");

        uint256 balanceBefore = address(bob).balance;
        vm.deal(alice, 10 ether);
        vm.prank(alice);
        c.multiplicate{value: 2 ether}(bob);
        uint256 balanceAfter = address(bob).balance;

        // Reference: msg.value (2) >= address(this).balance (3) is false → does NOT send → bob gets nothing
        // Buggy: msg.value (2) < address(this).balance (3) is true → sends 5 ether
        // So for the reference, balanceAfter == balanceBefore; for the buggy, balanceAfter > balanceBefore
        assertTrue(balanceAfter == balanceBefore);
    }
}
